        $(m.body, '#rcOn').onclick = async function () { this.disabled = true; try { await api.post('wa.rec_set', { on: R.cfg.on ? 0 : 1 }); R.cfg.on = !R.cfg.on; paint(); } catch (e) { toast(e.message, true); this.disabled = false; } };
